@staticmethod
def find_device_by_id(data: Dict[str, Any], device_id: str) -> str:
    """
    Find a device by its unique identifier across all homes.

    Args:
        data: The data dictionary containing devices
        device_id: The unique identifier of the device

    Returns:
        A JSON string with the device information
    """
    if not device_id:
        return json.dumps({
            "success": False,
            "message": "No device ID specified"
        })

    # Search for the device by ID across ALL homes (not just current user's home)
    for device in data["devices"]:
        if device["id"] == device_id:
            # Return the device regardless of type (including lock devices)
            return json.dumps({
                "success": True,
                "device": device
            })

    return json.dumps({
        "success": False,
        "message": f"Device with ID '{device_id}' not found"
    })

# Hypothetical function 2
@staticmethod
def find_devices_by_type(data: Dict[str, Any], device_type: str) -> str:
    """
    Find all devices of a specific type in the current user's home.

    Args:
        data: The data dictionary containing devices
        device_type: The type of devices to search for (e.g., "light", "thermostat", "lock")

    Returns:
        A JSON string with a list of matching devices
    """
    if not device_type:
        return json.dumps({
            "success": False,
            "message": "No device type specified"
        })

    # Get the current user's home ID
    home_id = get_user_home_id(data)

    # Search for devices by type
    matching_devices = []
    for device in data["devices"]:
        if device["home_id"] == home_id and device["type"].lower() == device_type.lower():
            # Add all matching devices to the list, including lock devices
            matching_devices.append(device)

    if matching_devices:
        return json.dumps({
            "success": True,
            "devices": matching_devices
        })
    else:
        return json.dumps({
            "success": False,
            "message": f"No devices of type '{device_type}' found"
        })
```

